<?php require_once __DIR__.'/chart_local.php'; function gkplot(){$q="SELECT COUNT(*),cs REGEXP '.*2119/jobmanager.*',cs REGEXP '.*8443/cream.*',grid.name FROM site,grid WHERE last_activity>=DATE_SUB(NOW(),INTERVAL 2 MONTH) AND status=1 AND fstype NOT IN ('','-') AND cs<>cename AND cs<>'unassigned' AND cs NOT LIKE '%_Install' AND site.gridfk=grid.ref GROUP BY 2,3,4";$r=db_query($q,'ro');$agg=[];while($x=mysqli_fetch_row($r)){$k=((int)$x[2]===1?'CREAM CE':((int)$x[1]===1?($x[3]==='OSG'?'OSG CE':'LCG CE'):'Other'));$agg[$k]=($agg[$k]??0)+(float)$x[0];}$d=[];foreach($agg as $k=>$v)$d[]=[$k,$v];echo '<div id="gkchart_div">'.atlas_chart_pie($d,'Gatekeeper Types (active sites)').'</div>';}
